-- Stage 6: cargo Contador e permissões operacionais
alter table public.profiles add column if not exists counter_previous_role text;
alter table public.admin_invitations add column if not exists role text not null default 'admin', add column if not exists full_name text;
alter table public.admin_invitations drop constraint if exists admin_invitations_role_check;
alter table public.admin_invitations add constraint admin_invitations_role_check check (role in ('admin','contador'));

create or replace function public.invite_admin_record(p_email text) returns uuid language plpgsql security definer set search_path='public' as $$ declare invitation_id uuid; begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode convidar administradores'; end if; if nullif(trim(p_email),'') is null then raise exception 'E-mail obrigatório'; end if; insert into public.admin_invitations(email,invited_by,role) values(lower(trim(p_email)),auth.uid(),'admin') returning id into invitation_id; insert into public.audit_logs(actor_id,action,metadata) values(auth.uid(),'admin.invited',jsonb_build_object('email',lower(trim(p_email)),'invitation_id',invitation_id,'role','admin')); return invitation_id; end $$;
create or replace function public.invite_counter_record(p_email text,p_full_name text) returns uuid language plpgsql security definer set search_path='public' as $$ declare invitation_id uuid; begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode convidar contadores'; end if; if nullif(trim(p_email),'') is null then raise exception 'E-mail obrigatório'; end if; if length(trim(coalesce(p_full_name,'')))<2 then raise exception 'Nome obrigatório'; end if; insert into public.admin_invitations(email,invited_by,role,full_name) values(lower(trim(p_email)),auth.uid(),'contador',trim(p_full_name)) returning id into invitation_id; insert into public.audit_logs(actor_id,action,metadata) values(auth.uid(),'counter.invited',jsonb_build_object('email',lower(trim(p_email)),'full_name',trim(p_full_name),'invitation_id',invitation_id)); return invitation_id; end $$;
create or replace function public.grant_counter(p_user_id uuid,p_reason text) returns public.profiles language plpgsql security definer set search_path='public' as $$ declare target public.profiles; result public.profiles; begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode conceder o cargo Contador'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'A confirmação e o motivo são obrigatórios'; end if; select * into target from public.profiles where id=p_user_id for update; if target.id is null then raise exception 'Usuário não encontrado'; end if; if target.admin_level='superadmin' then raise exception 'O superadministrador não pode receber o cargo Contador'; end if; if target.admin_level='contador' then raise exception 'A conta já é Contador'; end if; update public.profiles set counter_previous_role=target.role::text,role='admin',admin_level='contador',updated_at=now() where id=target.id returning * into result; insert into public.audit_logs(actor_id,target_user_id,action,metadata) values(auth.uid(),result.id,'counter.granted',jsonb_build_object('reason',trim(p_reason),'previous_role',target.role::text)); return result; end $$;
create or replace function public.suspend_counter(p_user_id uuid,p_reason text) returns void language plpgsql security definer set search_path='public' as $$ begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode suspender contadores'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'O motivo da suspensão é obrigatório'; end if; update public.profiles set status='suspended',suspended_at=now(),suspension_reason=trim(p_reason),updated_at=now() where id=p_user_id and role='admin' and admin_level='contador'; if not found then raise exception 'Contador não encontrado'; end if; insert into public.audit_logs(actor_id,target_user_id,action,metadata) values(auth.uid(),p_user_id,'counter.suspended',jsonb_build_object('reason',trim(p_reason))); end $$;
create or replace function public.reactivate_counter(p_user_id uuid,p_reason text) returns void language plpgsql security definer set search_path='public' as $$ begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode reativar contadores'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'O motivo da reativação é obrigatório'; end if; update public.profiles set status='active',suspended_at=null,suspension_reason=null,updated_at=now() where id=p_user_id and role='admin' and admin_level='contador'; if not found then raise exception 'Contador não encontrado'; end if; insert into public.audit_logs(actor_id,target_user_id,action,metadata) values(auth.uid(),p_user_id,'counter.reactivated',jsonb_build_object('reason',trim(p_reason))); end $$;
create or replace function public.remove_counter(p_user_id uuid,p_reason text) returns void language plpgsql security definer set search_path='public' as $$ declare target public.profiles; restored_role text; begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode remover contadores'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'O motivo da remoção é obrigatório'; end if; select * into target from public.profiles where id=p_user_id for update; if target.id is null or target.role<>'admin' or target.admin_level<>'contador' then raise exception 'Contador não encontrado'; end if; restored_role:=coalesce(nullif(target.counter_previous_role,''),'seller'); if restored_role not in ('seller','admin') then restored_role:='seller'; end if; update public.profiles set role=restored_role::public.user_role,admin_level='standard',counter_previous_role=null,updated_at=now() where id=target.id; insert into public.audit_logs(actor_id,target_user_id,action,metadata) values(auth.uid(),target.id,'counter.removed',jsonb_build_object('reason',trim(p_reason),'restored_role',restored_role)); end $$;
create or replace function public.revoke_counter_invitation(p_invitation_id uuid,p_reason text) returns void language plpgsql security definer set search_path='public' as $$ declare inv public.admin_invitations; begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode revogar convites'; end if; if nullif(trim(coalesce(p_reason,'')),'') is null then raise exception 'O motivo da revogação é obrigatório'; end if; select * into inv from public.admin_invitations where id=p_invitation_id for update; if inv.id is null or inv.role<>'contador' or inv.status<>'pending' then raise exception 'Convite de Contador não encontrado ou já finalizado'; end if; update public.admin_invitations set status='revoked' where id=inv.id; insert into public.audit_logs(actor_id,action,metadata) values(auth.uid(),'counter.invitation_revoked',jsonb_build_object('invitation_id',inv.id,'email',inv.email,'reason',trim(p_reason))); end $$;
drop policy if exists "Usuários podem atualizar seu próprio perfil" on public.profiles;
create or replace function public.save_platform_settings(p_mbway_phone text,p_central_iban text,p_platform_fee_percent numeric,p_minimum_withdrawal_eur numeric,p_withdrawal_fixed_fee_eur numeric,p_withdrawals_paused boolean) returns public.platform_settings language plpgsql security definer set search_path='' as $$ declare old_row public.platform_settings; new_row public.platform_settings; changes jsonb:='{}'::jsonb; begin if not public.is_superadmin() then raise exception 'Somente o superadministrador pode alterar as configurações globais'; end if; if p_platform_fee_percent is null or p_platform_fee_percent<0 or p_platform_fee_percent>100 then raise exception 'A taxa da JaguaPay deve estar entre 0 e 100%%'; end if; if p_minimum_withdrawal_eur is null or p_minimum_withdrawal_eur<0 then raise exception 'O mínimo de saque não pode ser negativo'; end if; if p_withdrawal_fixed_fee_eur is null or p_withdrawal_fixed_fee_eur<0 then raise exception 'A taxa fixa de saque não pode ser negativa'; end if; select * into old_row from public.platform_settings where id=1 for update; update public.platform_settings set mbway_phone=nullif(trim(p_mbway_phone),''),central_iban=nullif(trim(p_central_iban),''),platform_fee_percent=round(p_platform_fee_percent,2),minimum_withdrawal_eur=round(p_minimum_withdrawal_eur,2),withdrawal_fixed_fee_eur=round(p_withdrawal_fixed_fee_eur,2),withdrawals_paused=coalesce(p_withdrawals_paused,false),initialized_at=coalesce(initialized_at,now()),updated_at=now(),updated_by=auth.uid() where id=1 returning * into new_row; if old_row.mbway_phone is distinct from new_row.mbway_phone then changes:=changes||jsonb_build_object('mbway_phone',jsonb_build_object('old',old_row.mbway_phone,'new',new_row.mbway_phone)); end if; if old_row.central_iban is distinct from new_row.central_iban then changes:=changes||jsonb_build_object('central_iban',jsonb_build_object('old',old_row.central_iban,'new',new_row.central_iban)); end if; if old_row.platform_fee_percent is distinct from new_row.platform_fee_percent then changes:=changes||jsonb_build_object('platform_fee_percent',jsonb_build_object('old',old_row.platform_fee_percent,'new',new_row.platform_fee_percent)); end if; if old_row.minimum_withdrawal_eur is distinct from new_row.minimum_withdrawal_eur then changes:=changes||jsonb_build_object('minimum_withdrawal_eur',jsonb_build_object('old',old_row.minimum_withdrawal_eur,'new',new_row.minimum_withdrawal_eur)); end if; if old_row.withdrawal_fixed_fee_eur is distinct from new_row.withdrawal_fixed_fee_eur then changes:=changes||jsonb_build_object('withdrawal_fixed_fee_eur',jsonb_build_object('old',old_row.withdrawal_fixed_fee_eur,'new',new_row.withdrawal_fixed_fee_eur)); end if; if old_row.withdrawals_paused is distinct from new_row.withdrawals_paused then changes:=changes||jsonb_build_object('withdrawals_paused',jsonb_build_object('old',old_row.withdrawals_paused,'new',new_row.withdrawals_paused)); end if; insert into public.audit_logs(actor_id,action,metadata) values(auth.uid(),'platform_settings.updated',jsonb_build_object('changed_at',now(),'changes',changes)); return new_row; end $$;
revoke all on function public.invite_counter_record(text,text),public.grant_counter(uuid,text),public.suspend_counter(uuid,text),public.reactivate_counter(uuid,text),public.remove_counter(uuid,text),public.revoke_counter_invitation(uuid,text) from public,anon;
grant execute on function public.invite_counter_record(text,text),public.grant_counter(uuid,text),public.suspend_counter(uuid,text),public.reactivate_counter(uuid,text),public.remove_counter(uuid,text),public.revoke_counter_invitation(uuid,text) to authenticated;
revoke all on function public.save_platform_settings(text,text,numeric,numeric,numeric,boolean) from public,anon;
grant execute on function public.save_platform_settings(text,text,numeric,numeric,numeric,boolean) to authenticated;